oup -->\n\n<!-- wp:paragraph {\"className\":\"thryvewp-go-to-top\"} -->\n<p class=\"thryvewp-go-to-top\"></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->', 'Footer', '', 'inherit', 'closed', 'closed', '', '36-revision-v1', '', '', '2026-11-08 14:58:20', '2026-11-08 14:58:20', '', 36, 'http://localhost/literasi/?p=38', 0, 'revision', '', 0),
