(47, 1, '2026-11-09 06:58:14', '2026-11-09 06:58:14', '<!-- wp:navigation-link {\"label\":\"Kontak\",\"type\":\"page\",\"id\":16,\"url\":\"http://localhost/literasi/?page_id=16\",\"kind\":\"post-type\",\"metadata\":{\"bindings\":{\"url\":{\"source\":\"core/post-data\",\"args\":{\"field\":\"link\"}}}}} /-->\n\n<!-- wp:navigation-link {\"label\":\"Tentang Saya\",\"type\":\"page\",\"id\":14,\"url\":\"http://localhost/literasi/?page_id=14\",\"kind\":\"post-type\",\"metadata\":{\"bindings\":{\"url\":{\"source\":\"core/post-data\",\"args\":{\"field\":\"link\"}}}}} /-->\n\n<!-- wp:navigation-link {\"label\":\"Blog\",\"type\":\"page\",\"id\":46,\"url\":\"http://localhost/literasi/?page_id=46\",\"kind\":\"post-type\",\"metadata\":{\"bindings\":{\"url\":{\"source\":\"core/post-data\",\"args\":{\"field\":\"link\"}}}}} /-->', 'Navigasi', '', 'inherit', 'closed', 'closed', '', '4-revision-v1', '', '', '2026-11-09 06:58:14', '2026-11-09 06:58:14', '', 4, 'http://localhost/literasi/?p=47', 0, 'revision', '', 0);
