\":{\"spacing\":{\"padding\":{\"top\":\"8px\",\"bottom\":\"8px\",\"left\":\"var:preset|spacing|10\",\"right\":\"var:preset|spacing|10\"}},\"border\":{\"width\":\"0px\",\"style\":\"none\",\"radius\":{\"topLeft\":\"6px\",\"topRight\":\"6px\",\"bottomLeft\":\"6px\",\"bottomRight\":\"6px\"}},\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|white\"}}}},\"backgroundColor\":\"contrast\",\"textColor\":\"white\"} /--></div>\n<!-- /wp:group -->\n<!-- /wp:post-template -->\n\n<!-- wp:query-no-results -->\n<!-- wp:paragraph {\"placeholder\":\"Add text or blocks that will display when a query returns no results.\"} -->\n<p></p>\n<!-- /wp:paragraph -->\n<!-- /wp:query-no-results --></div>\n<!-- /wp:query --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"metadata\":{\"name\":\"Contact Us\",\"categories\":[\"thryve-creative-dark\"],\"patternName\":\"thryve-creative-dark/contact-us\"},\"className\":\"thryve-responsive-spacing wow animate__animated animate__fadeInUp\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"0\",\"bottom\":\"0\"},\"padding\":{\"top\":\"var:preset|spacing|50\",\"bottom\":\"var:preset|spacing|50\",\"left\":\"0\",\"right\":\"0\"}}},\"layout\":{\"type\":\"constrained\",\"contentSize\":\"\"}} -->\n<div class=\"wp-block-group thryve-responsive-spacing wow animate__animated animate__fadeInUp\" style=\"margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--50);padding-right:0;padding-bottom:var(--wp--preset--spacing--50);padding-left:0\"><!-- wp:columns {\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"40px\",\"left\":\"60px\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}}} -->\n<div class=\"wp-block-columns\" style=\"margin-top:0;margin-bottom:0\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:cover {\"url\":\"http://localhost/literasi/wp-content/themes/thryve-creative-dark/assets/images/contact.jpg\",\"id\":199,\"dimRatio\":30,\"overlayColor\":\"black\",\"isUserOverlayColor\":true,\"minHeight\":600,\"contentPosition\":\"bottom left\",\"sizeSlug\":\"full\",\"className\":\"thryve-has-effect thryve-has-box-shadow\",\"style\":{\"border\":{\"radius\":{\"topLeft\":\"10px\",\"topRight\":\"10px\",\"bottomLeft\":\"10px\",\"bottomRight\":\"10px\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-cover has-custom-content-position is-position-bottom-left thryve-has-effect thryve-has-box-shadow\" style=\"border-top-left-radius:10px;border-top-right-radius:10px;border-bottom-left-radius:10px;border-bottom-right-radius:10px;min-height:600px\"><img class=\"wp-block-cover__image-background wp-image-199 size-full\" alt=\"\" src=\"http://localhost/literasi/wp-content/themes/thryve-creative-dark/assets/images/contact.jpg\" data-object-fit=\"cover\"/><span aria-hidden=\"true\" class=\"wp-block-cover__background has-black-background-color has-background-dim-30 has-background-dim\"></span><div class=\"wp-block-cover__inner-container\"><!-- wp:paragraph {\"placeholder\":\"Write title…\",\"style\":{\"typography\":{\"textAlign\":\"center\"}},\"fontSize\":\"large\"} -->\n<p class=\"has-text-align-center has-large-font-size\"></p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:cover --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\"><!-- wp:group {\"className\":\"thryve-section-title-wrapper\",\"style\":{\"spacing\":{\"padding\":{\"bottom\":\"40px\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group thryve-section-title-wrapper\" style=\"padding-bottom:40px\"><!-- wp:heading {\"className\":\"is-style-default thryve-heading\",\"style\":{\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"700\",\"lineHeight\":\"1.2\",\"fontSize\":\"48px\",\"textAlign\":\"left\"},\"spacing\":{\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}},\"layout\":{\"selfStretch\":\"fit\",\"flexSize\":null},\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|white\"}}}},\"textColor\":\"white\"} -->\n<h2 class=\"wp-block-heading has-text-align-left is-style-default thryve-heading has-white-color has-text-color has-link-color\" style=\"margin-top:0;margin-bottom:0;font-size:48px;font-style:normal;font-weight:700;line-height:1.2\">Get A Free Quote</h2>\n<!-- /wp:heading -->\n\n<!-- wp:group {\"className\":\"contact-us\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"750px\"}} -->\n<div class=\"wp-block-group contact-us\"><!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"left\"}}} -->\n<p class=\"has-text-align-left\">Menerima masukan dan pertanyaan apapun!</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group --></main>\n<!-- /wp:group -->\n\n<!-- wp:template-part {\"slug\":\"footer\",\"theme\":\"thryve-creative-dark\",\"tagName\":\"footer\",\"area\":\"footer\"} /-->', 'Laman Depan', 'Menampilkan beranda situs Anda yang ditetapkan untuk menampilkan pos terbaru atau halaman statis. Templat Halaman Depan akan lebih diprioritaskan daripada semua templat lainnya.', 'inherit', 'closed', 'closed', '', '21-revision-v1', '', '', '2026-11-09 13:14:12', '2026-11-09 13:14:12', '', 21, 'http://localhost/literasi/?p=48', 0, 'revision', '', 0);
INSERT INTO `wpl_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(49, 1, '2026-11-09 14:07:34', '2026-11-09 14:07:34', '<!-- wp:image {\"id\":61,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"full\"} -->\n<figure class=\"wp-block-image alignfull size-full\"><img src=\"http://localhost/literasi/wp-content/uploads/2026/11/hacker2.png\" alt=\"\" class=\"wp-image-61\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>Keamanan akun digital bukan hanya teori, tetapi merupakan masalah nyata yang pernah dialami oleh banyak individu, perusahaan, bahkan platform digital besar. Kasus-kasus ini menunjukkan bahwa lemahnya perlindungan akun dapat menyebabkan pencurian data pribadi, pengambilalihan akun, penipuan, hingga kerugian finansial.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Berikut beberapa contoh kasus nyata yang dapat dijadikan bahan pembahasan dengan tema \"Lindungi Akunmu Sekarang!\"</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">1. Kebocoran Data Pengguna Tokopedia (2020)</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p><a href=\"https://images.openai.com/static-rsc-4/sCq8nzgf-aHMBUM09ZoBjiNn64jke884DtAdfil0FtEB3vdaRunt1f09rQKHmsxW7FGX42oX5WHcDtvKV7cRFPjjMvfP-zXMFxmTiPuuapAiObEwGjBAgOWB4iaGjxusaeV65-LbOoOSqDHLMhods9-lwuT7nCx5qURiQ5DjdCk?purpose=inline\">Top 10 Indonesian Online Shopping Sites You Can’t Miss｜Buy&amp;Ship Malaysia</a></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Platform: Tokopedia<br>Tahun: 2020</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Kebocoran data</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Pada Mei 2020, Tokopedia menjadi sorotan setelah muncul laporan mengenai dugaan kebocoran data pengguna. Data yang diduga bocor dilaporkan mencakup informasi akun seperti nama, alamat email, dan informasi terkait pengguna.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Kementerian Komunikasi dan Informatika saat itu meminta Tokopedia melakukan investigasi internal, mengamankan sistem, serta memberikan pemberitahuan kepada pengguna yang kemungkinan terdampak. JDIH Komdigi</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Dampak:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Informasi pribadi pengguna berpotensi disalahgunakan.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Pengguna berisiko menerima pesan penipuan yang memanfaatkan informasi pribadi.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Kepercayaan masyarakat terhadap keamanan platform digital dapat menurun.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>Pelajaran: Perusahaan harus menjaga keamanan database pengguna, sedangkan pengguna perlu menggunakan kata sandi unik dan mengaktifkan verifikasi tambahan.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">2. Peretasan Akun Facebook (2018)</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Platform: Facebook<br>Tahun: 2018</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Account takeover</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Pada September 2018, Facebook mengumumkan adanya celah keamanan pada fitur View As. Celah tersebut dimanfaatkan penyerang untuk mencuri access token, yaitu semacam kunci digital yang memungkinkan seseorang tetap masuk ke akun tanpa memasukkan kata sandi setiap kali.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Awalnya, Facebook memperkirakan hampir 50 juta akun terdampak. Setelah investigasi, sekitar 30 juta akun diketahui benar-benar mengalami pencurian access token. About Facebook+1</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Dampak:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Informasi akun pengguna berpotensi diakses pihak tidak berwenang.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Pengguna berisiko kehilangan kendali atas akun.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Facebook harus mengatur ulang token akses untuk mengamankan akun yang terdampak.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>Pelajaran: Keamanan akun tidak hanya bergantung pada kekuatan kata sandi, tetapi juga pada keamanan sistem dan fitur yang digunakan oleh platform.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">3. Peretasan Akun Twitter/X (2020)</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p><a href=\"https://images.openai.com/static-rsc-4/Y3PFDX2b9o8z-6mRBRIt7pQFw9cxLBiO8XOWK2M-MTmjT-VzQA7gfSo1-HxfRCWrap7IMSrqVvet3d5HMKEL1C5aLafOV5nZGbomixnA0nEx7loM0c-uET2ADZBjBvr6tXeKn7FO99RUtDLCovfSMO93tBgY7MI3iPpV-PUehwE?purpose=inline\">Riwayat Logo Baru Twitter X, Sudah Berganti Ikon hingga Lima Kali - Sejarah Ekonomi Katadata.co.id</a></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Platform: Twitter (sekarang X)<br>Tahun: 2020</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Social engineering</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Pada 15 Juli 2020, Twitter mengalami insiden keamanan besar. Penyerang menggunakan teknik social engineering untuk menargetkan sejumlah karyawan Twitter.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Setelah mendapatkan akses ke sistem internal, pelaku berhasil mengambil alih sejumlah akun terkenal, termasuk akun Barack Obama, Elon Musk, dan Bill Gates.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Akun-akun tersebut kemudian digunakan untuk menyebarkan penipuan yang berkaitan dengan Bitcoin. X Blog+1</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Dampak:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Sejumlah akun terkenal kehilangan kendali untuk sementara.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Masyarakat berpotensi tertipu oleh unggahan penipuan.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Reputasi dan kepercayaan terhadap keamanan Twitter terganggu.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>Pelajaran: Jangan mudah percaya kepada pihak yang meminta informasi rahasia, sekalipun mengaku sebagai petugas resmi. Keamanan juga harus diterapkan kepada karyawan dan pengelola sistem.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">4. Kebocoran Data Yahoo (2013)</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p><a href=\"https://images.openai.com/static-rsc-4/Ki0NTiY_3tgvA8HdgUV6Tzr3BopT2wUMcg5CeSj_R_ueuQNgWjSWYyomXlQkwSX5JqJQ8qXrJgPBZ3Ie2vo3GmRC5eIj8Y1hpMewnUXhuOR0Dc__U-UY-GKzBOUvaVLKlXHnu9kr-zHY8pYG1_pAiCIkt0cBJvqfPoChowIzGK4?purpose=inline\">Logo Yahoo! – Logos PNG</a></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Platform: Yahoo<br>Tahun: 2013 (diumumkan pada 2016–2017)</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Kebocoran skala besar</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Yahoo mengalami salah satu kebocoran data terbesar dalam sejarah internet. Pada Agustus 2013, pihak tidak berwenang mencuri data yang berkaitan dengan seluruh akun Yahoo yang ada saat itu.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Pada Oktober 2017, Yahoo mengumumkan bahwa hasil investigasi menunjukkan sekitar 3 miliar akun terdampak.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Informasi yang dicuri dapat mencakup nama, alamat email, tanggal lahir, nomor telepon, dan informasi keamanan akun. Yahoo menyatakan bahwa kata sandi dalam bentuk teks biasa serta data kartu pembayaran tidak termasuk dalam pencurian tersebut. Komisi Sekuritas dan Bursa+1</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Dampak:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Informasi pribadi pengguna dalam jumlah sangat besar terekspos.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Risiko penipuan dan pencurian identitas meningkat.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Yahoo menghadapi penurunan kepercayaan pengguna.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>Pelajaran: Perusahaan harus memiliki sistem perlindungan database yang kuat dan melakukan pemantauan keamanan secara berkala.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">5. Perbandingan Kasus Keamanan Akun</h2>\n<!-- /wp:heading -->\n\n<!-- wp:table -->\n<figure class=\"wp-block-table\"><table class=\"has-fixed-layout\"><tbody><tr><th>Kasus</th><th>Jenis ancaman</th><th>Dampak utama</th></tr><tr><td>Tokopedia (2020)</td><td>Data breach</td><td>Informasi pengguna terekspos</td></tr><tr><td>Facebook (2018)</td><td>Pencurian access token</td><td>Akun berpotensi diambil alih</td></tr><tr><td>Twitter/X (2020)</td><td>Social engineering</td><td>Akun terkenal diretas</td></tr><tr><td>Yahoo (2013)</td><td>Data breach</td><td>Sekitar 3 miliar akun terdampak</td></tr></tbody></table></figure>\n<!-- /wp:table -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">6. Kesimpulan dan Pesan yang Dapat Diambil</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Dari keempat kasus tersebut, kita dapat memahami bahwa ancaman keamanan akun digital bisa terjadi kepada siapa saja, baik pengguna biasa maupun perusahaan teknologi besar.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Ada tiga hal penting yang dapat kita pelajari:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list {\"ordered\":true} -->\n<ol class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Jaga informasi pribadi. Jangan sembarangan memberikan kata sandi, OTP, maupun informasi akun kepada orang lain.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Tingkatkan keamanan akun. Gunakan kata sandi yang kuat dan aktifkan Two-Factor Authentication (2FA).</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Selalu waspada. Jangan mudah percaya terhadap pesan, tautan, atau permintaan informasi yang mencurigakan.</li>\n<!-- /wp:list-item --></ol>\n<!-- /wp:list -->', 'Kasus-Kasus Nyata yang Pernah Terjadi Mengenai Keamanan Akun Digital', '', 'publish', 'open', 'open', '', 'kasus-kasus-nyata-yang-pernah-terjadi-mengenai-keamanan-akun-digital', '', '', '2026-11-10 13:18:37', '2026-11-10 13:18:37', '', 0, 'http://localhost/literasi/?p=49', 0, 'post', '', 0),
(50, 1, '2026-11-09 14:07:34', '2026-11-09 14:07:34', '<!-- wp:paragraph -->\n<p>Keamanan akun digital bukan hanya teori, tetapi merupakan masalah nyata yang pernah dialami oleh banyak individu, perusahaan, bahkan platform digital besar. Kasus-kasus ini menunjukkan bahwa lemahnya perlindungan akun dapat menyebabkan pencurian data pribadi, pengambilalihan akun, penipuan, hingga kerugian finansial.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Berikut beberapa contoh kasus nyata yang dapat dijadikan bahan pembahasan dengan tema \"Lindungi Akunmu Sekarang!\"</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">1. Kebocoran Data Pengguna Tokopedia (2020)</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p><a href=\"https://images.openai.com/static-rsc-4/sCq8nzgf-aHMBUM09ZoBjiNn64jke884DtAdfil0FtEB3vdaRunt1f09rQKHmsxW7FGX42oX5WHcDtvKV7cRFPjjMvfP-zXMFxmTiPuuapAiObEwGjBAgOWB4iaGjxusaeV65-LbOoOSqDHLMhods9-lwuT7nCx5qURiQ5DjdCk?purpose=inline\">Top 10 Indonesian Online Shopping Sites You Can’t Miss｜Buy&amp;Ship Malaysia</a></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Platform: Tokopedia<br>Tahun: 2020</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Kebocoran data</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Pada Mei 2020, Tokopedia menjadi sorotan setelah muncul laporan mengenai dugaan kebocoran data pengguna. Data yang diduga bocor dilaporkan mencakup informasi akun seperti nama, alamat email, dan informasi terkait pengguna.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Kementerian Komunikasi dan Informatika saat itu meminta Tokopedia melakukan investigasi internal, mengamankan sistem, serta memberikan pemberitahuan kepada pengguna yang kemungkinan terdampak. JDIH Komdigi</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Dampak:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Informasi pribadi pengguna berpotensi disalahgunakan.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Pengguna berisiko menerima pesan penipuan yang memanfaatkan informasi pribadi.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Kepercayaan masyarakat terhadap keamanan platform digital dapat menurun.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>Pelajaran: Perusahaan harus menjaga keamanan database pengguna, sedangkan pengguna perlu menggunakan kata sandi unik dan mengaktifkan verifikasi tambahan.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">2. Peretasan Akun Facebook (2018)</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p><a href=\"https://images.openai.com/static-rsc-4/8Sd9ajbNpQnPTMMru04ksrhCFoifC2GB3kixZ3KrvVhp-XiLkid77QORZKviZzhBk4t5tIqwPNvq2NRdf4VeryB_6BEDiUXsq4UJbn_R1WG6QJJMl-_tyQh6z9bHeaJg5utHo6HO9BhapH6-NumvlqqY6OLAP36HruWa-hvXRAE?purpose=inline\">Home</a></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Platform: Facebook<br>Tahun: 2018</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Account takeover</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Pada September 2018, Facebook mengumumkan adanya celah keamanan pada fitur View As. Celah tersebut dimanfaatkan penyerang untuk mencuri access token, yaitu semacam kunci digital yang memungkinkan seseorang tetap masuk ke akun tanpa memasukkan kata sandi setiap kali.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Awalnya, Facebook memperkirakan hampir 50 juta akun terdampak. Setelah investigasi, sekitar 30 juta akun diketahui benar-benar mengalami pencurian access token. About Facebook+1</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Dampak:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Informasi akun pengguna berpotensi diakses pihak tidak berwenang.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Pengguna berisiko kehilangan kendali atas akun.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Facebook harus mengatur ulang token akses untuk mengamankan akun yang terdampak.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>Pelajaran: Keamanan akun tidak hanya bergantung pada kekuatan kata sandi, tetapi juga pada keamanan sistem dan fitur yang digunakan oleh platform.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">3. Peretasan Akun Twitter/X (2020)</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p><a href=\"https://images.openai.com/static-rsc-4/Y3PFDX2b9o8z-6mRBRIt7pQFw9cxLBiO8XOWK2M-MTmjT-VzQA7gfSo1-HxfRCWrap7IMSrqVvet3d5HMKEL1C5aLafOV5nZGbomixnA0nEx7loM0c-uET2ADZBjBvr6tXeKn7FO99RUtDLCovfSMO93tBgY7MI3iPpV-PUehwE?purpose=inline\">Riwayat Logo Baru Twitter X, Sudah Berganti Ikon hingga Lima Kali - Sejarah Ekonomi Katadata.co.id</a></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Platform: Twitter (sekarang X)<br>Tahun: 2020</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Social engineering</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Pada 15 Juli 2020, Twitter mengalami insiden keamanan besar. Penyerang menggunakan teknik social engineering untuk menargetkan sejumlah karyawan Twitter.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Setelah mendapatkan akses ke sistem internal, pelaku berhasil mengambil alih sejumlah akun terkenal, termasuk akun Barack Obama, Elon Musk, dan Bill Gates.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Akun-akun tersebut kemudian digunakan untuk menyebarkan penipuan yang berkaitan dengan Bitcoin. X Blog+1</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Dampak:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Sejumlah akun terkenal kehilangan kendali untuk sementara.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Masyarakat berpotensi tertipu oleh unggahan penipuan.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Reputasi dan kepercayaan terhadap keamanan Twitter terganggu.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>Pelajaran: Jangan mudah percaya kepada pihak yang meminta informasi rahasia, sekalipun mengaku sebagai petugas resmi. Keamanan juga harus diterapkan kepada karyawan dan pengelola sistem.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">4. Kebocoran Data Yahoo (2013)</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p><a href=\"https://images.openai.com/static-rsc-4/Ki0NTiY_3tgvA8HdgUV6Tzr3BopT2wUMcg5CeSj_R_ueuQNgWjSWYyomXlQkwSX5JqJQ8qXrJgPBZ3Ie2vo3GmRC5eIj8Y1hpMewnUXhuOR0Dc__U-UY-GKzBOUvaVLKlXHnu9kr-zHY8pYG1_pAiCIkt0cBJvqfPoChowIzGK4?purpose=inline\">Logo Yahoo! – Logos PNG</a></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Platform: Yahoo<br>Tahun: 2013 (diumumkan pada 2016–2017)</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Kebocoran skala besar</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Yahoo mengalami salah satu kebocoran data terbesar dalam sejarah internet. Pada Agustus 2013, pihak tidak berwenang mencuri data yang berkaitan dengan seluruh akun Yahoo yang ada saat itu.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Pada Oktober 2017, Yahoo mengumumkan bahwa hasil investigasi menunjukkan sekitar 3 miliar akun terdampak.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Informasi yang dicuri dapat mencakup nama, alamat email, tanggal lahir, nomor telepon, dan informasi keamanan akun. Yahoo menyatakan bahwa kata sandi dalam bentuk teks biasa serta data kartu pembayaran tidak termasuk dalam pencurian tersebut. Komisi Sekuritas dan Bursa+1</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Dampak:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Informasi pribadi pengguna dalam jumlah sangat besar terekspos.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Risiko penipuan dan pencurian identitas meningkat.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Yahoo menghadapi penurunan kepercayaan pengguna.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>Pelajaran: Perusahaan harus memiliki sistem perlindungan database yang kuat dan melakukan pemantauan keamanan secara berkala.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">5. Perbandingan Kasus Keamanan Akun</h2>\n<!-- /wp:heading -->\n\n<!-- wp:table -->\n<figure class=\"wp-block-table\"><table class=\"has-fixed-layout\"><tbody><tr><th>Kasus</th><th>Jenis ancaman</th><th>Dampak utama</th></tr><tr><td>Tokopedia (2020)</td><td>Data breach</td><td>Informasi pengguna terekspos</td></tr><tr><td>Facebook (2018)</td><td>Pencurian access token</td><td>Akun berpotensi diambil alih</td></tr><tr><td>Twitter/X (2020)</td><td>Social engineering</td><td>Akun terkenal diretas</td></tr><tr><td>Yahoo (2013)</td><td>Data breach</td><td>Sekitar 3 miliar akun terdampak</td></tr></tbody></table></figure>\n<!-- /wp:table -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">6. Kesimpulan dan Pesan yang Dapat Diambil</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Dari keempat kasus tersebut, kita dapat memahami bahwa ancaman keamanan akun digital bisa terjadi kepada siapa saja, baik pengguna biasa maupun perusahaan teknologi besar.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Ada tiga hal penting yang dapat kita pelajari:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list {\"ordered\":true} -->\n<ol class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Jaga informasi pribadi. Jangan sembarangan memberikan kata sandi, OTP, maupun informasi akun kepada orang lain.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Tingkatkan keamanan akun. Gunakan kata sandi yang kuat dan aktifkan Two-Factor Authentication (2FA).</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Selalu waspada. Jangan mudah percaya terhadap pesan, tautan, atau permintaan informasi yang mencurigakan.</li>\n<!-- /wp:list-item --></ol>\n<!-- /wp:list -->', 'Kasus-Kasus Nyata yang Pernah Terjadi Mengenai Keamanan Akun Digital', '', 'inherit', 'closed', 'closed', '', '49-revision-v1', '', '', '2026-11-09 14:07:34', '2026-11-09 14:07:34', '', 49, 'http://localhost/literasi/?p=50', 0, 'revision', '', 0),
